from pwn import *
import re

def analyze_cursor_movements():
    conn = remote('misc.chal.csaw.io', 3535)

    # Track cursor position and characters
    current_pos = [1, 1]  # [row, col]
    char_sequence = []
    screen = [[' ' for _ in range(80)] for _ in range(24)]

    try:
        while True:
            try:
                data = conn.recv(1)
                if not data:
                    break

                # Convert to hex for analysis
                hex_val = hex(ord(data))[2:].zfill(2)

                # Track escape sequences for cursor movement
                if data == b'\x1b':  # ESC character
                    seq = conn.recv_raw(timeout=0.1)
                    if b'[' in seq:
                        # This is a cursor movement or screen control sequence
                        if b';' in seq:
                            # Direct cursor positioning
                            matches = re.findall(rb'\[(\d+);(\d+)H', seq)
                            if matches:
                                current_pos = [int(matches[0][0]), int(matches[0][1])]
                elif data.decode('latin-1').isprintable():
                    char = data.decode('latin-1')
                    char_sequence.append((char, current_pos[0], current_pos[1]))
                    screen[current_pos[0]-1][current_pos[1]-1] = char
                    current_pos[1] += 1  # Move cursor right

                # Check for password prompt and respond
                if b'Enter the password:' in conn.recv_raw(timeout=0.1):
                    # Extract last written characters that might form the password
                    password = ''.join([c[0] for c in char_sequence[-20:] if c[0].isalnum()])
                    conn.sendline(password.encode())

            except EOFError:
                break
            except Exception as e:
                continue

    finally:
        conn.close()

    # Analyze the character sequence
    print("\nCharacter sequence with positions:")
    for char, row, col in char_sequence:
        if char.isalnum():  # Focus on alphanumeric characters
            print(f"Character '{char}' at position ({row}, {col})")

    # Print the final screen state for the relevant rows
    print("\nFinal screen state (relevant rows):")
    for i, row in enumerate(screen):
        if any(c != ' ' for c in row):
            print(f"Row {i+1}: {''.join(row)}")

    # Look for patterns in character placement
    print("\nAnalyzing character placement patterns:")
    col_chars = {}
    for char, row, col in char_sequence:
        if char.isalnum():
            if col not in col_chars:
                col_chars[col] = []
            col_chars[col].append(char)

    # Print column patterns
    for col in sorted(col_chars.keys()):
        chars = col_chars[col]
        if len(chars) > 1:
            print(f"Column {col}: {''.join(chars)}")

if __name__ == "__main__":
    analyze_cursor_movements()

