from pwn import *

def analyze_velocity():
    conn = remote('misc.chal.csaw.io', 3535)
    buffer = ''
    velocity_positions = []

    while True:
        try:
            c = conn.recv(1)
            if not c:
                break

            # Skip escape sequences
            if c == b'\x1b':
                while True:
                    next_c = conn.recv(1)
                    if next_c.decode('latin-1', errors='ignore').isalpha():
                        break
                continue

            char = c.decode('latin-1', errors='ignore')
            if char.isprintable():
                buffer += char
                if 'velocity' in buffer.lower():
                    start_pos = buffer.lower().find('velocity')
                    velocity_str = buffer[start_pos:start_pos+8]
                    log.info(f"Found velocity pattern: {velocity_str}")
                    log.info(f"Context: {buffer[max(0,start_pos-10):start_pos+18]}")
                    velocity_positions.append({
                        'position': start_pos,
                        'case': velocity_str,
                        'context': buffer[max(0,start_pos-10):start_pos+18]
                    })

        except EOFError:
            break

    log.info("\n=== Velocity Analysis ===")
    for i, pos in enumerate(velocity_positions):
        log.info(f"\nInstance {i+1}:")
        log.info(f"Case: {pos['case']}")
        log.info(f"Position: {pos['position']}")
        log.info(f"Context: {pos['context']}")

    conn.close()

if __name__ == '__main__':
    analyze_velocity()

